def dump(path, obj):
    path.write_text(json.dumps(obj, indent=2)+'\n')
def record(skill, request, raw, data, mapping, issues=None, obj='CLM-WATER-731', line='commercial_property'):
    dest = OUT/skill
    (dest/'raw_sources').mkdir(parents=True,exist_ok=True)
    (dest/'snapshot').mkdir(exist_ok=True)
    srcs=[]
    for source_ref,body in raw.items():
        p=dest/'raw_sources'/f'{source_ref}.md'
        p.write_text('# SYNTHETIC SOURCE — invented for independent forward evaluation\n\n'+body+'\n')
        srcs.append({'source_ref':source_ref,'version':'1','as_of':'2026-09-18','path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
    profile_ref='REVIEW-PROFILE'
    profile_body=f'Synthetic reviewed operating profile. Version 1. Reviewed by the fictional insurer subject-matter owner on 2026-09-18. Effective 2026-01-01 through 2026-12-31. Scope: US-NY; {line}. Authorizes preparation of internal draft evidence reviews only. These are supplied case conventions, not representations of law. No legal deadlines, payment authority, coverage or product approval may be inferred.'
    p=dest/'raw_sources'/f'{profile_ref}.md';p.write_text(profile_body+'\n')
    srcs.append({'source_ref':profile_ref,'version':'1','as_of':'2026-09-18','path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
    doc={'case_id':'FWD-'+skill,'as_of':'2026-09-18','context':{'capacity':'internal insurer analyst preparing draft for authorized reviewer','represented_party':'Fictional Harbor Mutual Insurance','object_id':obj,'jurisdiction':'US-NY','line_of_business':line},'sources':srcs,'unresolved_issues':issues or [],'rule_profile':{'profile_id':'SYNTHETIC-REVIEW-'+skill,'version':'1','source_refs':[profile_ref],'effective_from':'2026-01-01','effective_to':'2026-12-31','jurisdictions':['US-NY'],'lines_of_business':[line]},'data':data}
    dump(dest/'input.json',doc)
    (dest/'request.md').write_text('# Fresh practitioner request\n\n'+request+'\n\nAll parties, facts, records, wording and profiles in this packet are synthetic. Internal draft only; no external delivery or execution.\n')
    (dest/'mapping.md').write_text('# Raw-source to native-input mapping\n\n'+mapping+'\n\nSource registry paths and SHA-256 values bind each native source_ref to the exact raw artifact. Source_ref/version values are synthetic identifiers; hashes establish file identity, not truth. Missing amounts remain null. No example, evaluation, golden answer, or prior audit was read to design this case.\n')
    hashes={}
    for p in (ROOT/'skills/insurance'/skill).rglob('*'):
        if p.is_file() and p.name!='test_phase2.py' and 'evals' not in p.parts and '__pycache__' not in p.parts:
            rel=p.relative_to(ROOT/'skills/insurance'/skill)
            destp=dest/'snapshot'/rel;destp.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(p,destp)
            hashes[str(rel)]=hashlib.sha256(p.read_bytes()).hexdigest()
    dump(dest/'implementation-source-hashes.json',hashes)

